// Based on steam-vent-proto (MIT); see README.md and LICENSE-MIT.
//! Protobuf messages of the Steam client protocol, with the traits
//! [`gaki-steam-vent`] uses to send them.
//!
//! Fork of [steam-vent-proto] (`steam-vent-proto`, `-common` and `-steam` in
//! one crate). The bindings are generated by `build.rs` from `protos/`, so
//! they always match the `protobuf` runtime the workspace pins.
//!
//! [`gaki-steam-vent`]: https://github.com/Gigas002/gaki
//! [steam-vent-proto]: https://codeberg.org/steam-vent/proto

mod common;
mod generated;

pub use common::*;
pub use generated::*;

impl JobMultiple for steammessages_clientserver_appinfo::CMsgClientPICSProductInfoResponse {
    fn completed(&self) -> bool {
        !self.response_pending.unwrap_or(false)
    }
}
